cat > /etc/nginx/conf.d/port-6700.conf <<'ANTRIEB_EOF'
server {
    listen 6700 default_server;
    listen [::]:6700 default_server;
    server_name _;

    location / {
        default_type text/plain;
        return 200 "nginx is serving on port 6700\n";
    }
}
ANTRIEB_EOF
sed -n '1,120p' /etc/nginx/conf.d/port-6700.conf

